INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000630', 'Permeabilitas batuan adalah ukuran kemampuan batuan untuk...', 'Rock permeability is a measure of the rock''s ability to...', 'option', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:16:"Menyimpan fluida";i:1;s:18:"Mengalirkan fluida";i:2;s:26:"Menahan tekanan overburden";i:3;s:14:"Menyerap panas";}', 'a:4:{i:0;s:12:"Store fluids";i:1;s:11:"Flow fluids";i:2;s:29:"Withstand overburden pressure";i:3;s:11:"Absorb heat";}', '', 'Mengalirkan fluida', 'Flow fluids', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000631', 'Satuan yang paling umum dipakai untuk permeabilitas batuan reservoir adalah...', 'The most common unit used for reservoir rock permeability is...', 'option', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:7:"gram/cc";i:1;s:14:"miliDarcy (mD)";i:2;s:3:"psi";i:3;s:1:"%";}', 'a:4:{i:0;s:7:"gram/cc";i:1;s:15:"milliDarcy (mD)";i:2;s:3:"psi";i:3;s:1:"%";}', '', 'miliDarcy (mD)', 'milliDarcy (mD)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000632', 'Permeabilitas absolut diukur ketika batuan dijenuhi oleh...', 'Absolute permeability is measured when the rock is saturated with...', 'option', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:21:"Gas dan air bersamaan";i:1;s:20:"Dua fluida sekaligus";i:2;s:38:"Satu jenis fluida saja (100% saturasi)";i:3;s:26:"Fluida dengan saturasi 50%";}', 'a:4:{i:0;s:22:"Gas and water together";i:1;s:18:"Two fluids at once";i:2;s:37:"A single fluid only (100% saturation)";i:3;s:25:"A fluid at 50% saturation";}', '', 'Satu jenis fluida saja (100% saturasi)', 'A single fluid only (100% saturation)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000633', 'Permeabilitas efektif adalah permeabilitas terhadap suatu fluida pada kondisi...', 'Effective permeability is the permeability to a given fluid under conditions of...', 'option', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:21:"Tekanan atmosfer saja";i:1;s:38:"Saturasi fluida tertentu di dalam pori";i:2;s:13:"Batuan kosong";i:3;s:15:"Aliran turbulen";}', 'a:4:{i:0;s:25:"Atmospheric pressure only";i:1;s:44:"A specific fluid saturation within the pores";i:2;s:13:"An empty rock";i:3;s:14:"Turbulent flow";}', '', 'Saturasi fluida tertentu di dalam pori', 'A specific fluid saturation within the pores', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000634', 'Hukum Darcy menghubungkan laju alir fluida dengan...', 'Darcy''s law relates fluid flow rate to...', 'option', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:26:"Warna batuan dan porositas";i:1;s:20:"Kedalaman sumur saja";i:2;s:22:"Kadar lempung dan suhu";i:3;s:47:"Gradien tekanan, luas penampang, dan viskositas";}', 'a:4:{i:0;s:23:"Rock color and porosity";i:1;s:15:"Well depth only";i:2;s:28:"Clay content and temperature";i:3;s:54:"Pressure gradient, cross-sectional area, and viscosity";}', '', 'Gradien tekanan, luas penampang, dan viskositas', 'Pressure gradient, cross-sectional area, and viscosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000635', 'Batuan dengan permeabilitas 1 mD termasuk kategori...', 'A rock with 1 mD permeability falls into the category...', 'option', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:13:"Sangat tinggi";i:1;s:6:"Rendah";i:2;s:20:"Sangat tinggi sekali";i:3;s:18:"Tidak dapat diukur";}', 'a:4:{i:0;s:9:"Very high";i:1;s:3:"Low";i:2;s:14:"Extremely high";i:3;s:12:"Unmeasurable";}', '', 'Rendah', 'Low', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000636', 'Pernyataan yang benar tentang hubungan porositas dan permeabilitas adalah...', 'The correct statement about the relationship between porosity and permeability is...', 'option', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:52:"Porositas tinggi selalu berarti permeabilitas tinggi";i:1;s:42:"Keduanya tidak selalu berkorelasi langsung";i:2;s:29:"Keduanya selalu bernilai sama";i:3;s:47:"Permeabilitas selalu lebih besar dari porositas";}', 'a:4:{i:0;s:44:"High porosity always means high permeability";i:1;s:39:"They are not always directly correlated";i:2;s:21:"They are always equal";i:3;s:44:"Permeability is always greater than porosity";}', '', 'Keduanya tidak selalu berkorelasi langsung', 'They are not always directly correlated', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000637', 'Faktor apa saja yang memengaruhi permeabilitas batuan?', 'Which factors affect rock permeability?', 'multi', 'PFC000000002', 'Inisialisasi', 'a:4:{i:0;s:17:"Tingkat sementasi";i:1;s:12:"Warna batuan";i:2;s:12:"Ukuran butir";i:3;s:25:"Pemilahan (sorting) butir";}', 'a:4:{i:0;s:21:"Degree of cementation";i:1;s:10:"Rock color";i:2;s:10:"Grain size";i:3;s:13:"Grain sorting";}', '', 'a:3:{i:0;s:12:"Ukuran butir";i:1;s:25:"Pemilahan (sorting) butir";i:2;s:17:"Tingkat sementasi";}', 'a:3:{i:0;s:10:"Grain size";i:1;s:13:"Grain sorting";i:2;s:21:"Degree of cementation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000638', 'Urutkan ukuran butir sedimen dari yang paling kasar ke paling halus.', 'Arrange sediment grain sizes from coarsest to finest.', 'drag', 'PFC000000002', 'Inisialisasi', 'a:6:{i:0;s:16:"Kerikil (gravel)";i:1;s:18:"Pasir sangat kasar";i:2;s:11:"Pasir halus";i:3;s:22:"Batuan dasar (bedrock)";i:4;s:12:"Lanau (silt)";i:5;s:14:"Lempung (clay)";}', 'a:6:{i:0;s:6:"Gravel";i:1;s:16:"Very coarse sand";i:2;s:9:"Fine sand";i:3;s:7:"Bedrock";i:4;s:4:"Silt";i:5;s:4:"Clay";}', '', 'a:5:{i:0;s:16:"Kerikil (gravel)";i:1;s:18:"Pasir sangat kasar";i:2;s:11:"Pasir halus";i:3;s:12:"Lanau (silt)";i:4;s:14:"Lempung (clay)";}', 'a:5:{i:0;s:6:"Gravel";i:1;s:16:"Very coarse sand";i:2;s:9:"Fine sand";i:3;s:4:"Silt";i:4;s:4:"Clay";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000639', 'Benarkah permeabilitas absolut hanya bergantung pada sifat batuan, bukan pada jenis fluida yang mengalir?', 'Is it true that absolute permeability depends only on rock properties, not on the type of flowing fluid?', 'yesorno', 'PFC000000002', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000640', 'Aliran 10 cm3/s melewati core dengan luas 20 cm2 dan panjang 10 cm pada beda tekanan 2 atm, viskositas 1 cp. Berapa permeabilitasnya?', 'A flow of 10 cm3/s passes through a core of 20 cm2 area and 10 cm length at a pressure difference of 2 atm and viscosity of 1 cp. What is the permeability?', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:10:"0,25 Darcy";i:1;s:9:"2,5 Darcy";i:2;s:8:"25 Darcy";i:3;s:9:"250 Darcy";}', 'a:4:{i:0;s:10:"0.25 Darcy";i:1;s:9:"2.5 Darcy";i:2;s:8:"25 Darcy";i:3;s:9:"250 Darcy";}', '', '2,5 Darcy', '2.5 Darcy', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000641', 'Nilai 1 Darcy setara dengan...', 'A value of 1 Darcy is equivalent to...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:12:"1 x 10-15 m2";i:1;s:11:"1 x 10-3 m2";i:2;s:15:"9,87 x 10-13 m2";i:3;s:14:"9,87 x 10-9 m2";}', 'a:4:{i:0;s:12:"1 x 10-15 m2";i:1;s:11:"1 x 10-3 m2";i:2;s:15:"9.87 x 10-13 m2";i:3;s:14:"9.87 x 10-9 m2";}', '', '9,87 x 10-13 m2', '9.87 x 10-13 m2', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000642', 'Efek Klinkenberg menyebabkan permeabilitas yang diukur dengan gas...', 'The Klinkenberg effect causes permeability measured with gas to be...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:38:"Lebih tinggi dari permeabilitas cairan";i:1;s:13:"Tidak terukur";i:2;s:38:"Lebih rendah dari permeabilitas cairan";i:3;s:39:"Sama persis dengan permeabilitas cairan";}', 'a:4:{i:0;s:31:"Higher than liquid permeability";i:1;s:12:"Unmeasurable";i:2;s:30:"Lower than liquid permeability";i:3;s:36:"Exactly equal to liquid permeability";}', '', 'Lebih tinggi dari permeabilitas cairan', 'Higher than liquid permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000643', 'Pada batuan berlapis (bedded), rasio permeabilitas vertikal terhadap horizontal (kv/kh) umumnya...', 'In bedded rocks, the ratio of vertical to horizontal permeability (kv/kh) is generally...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:20:"Selalu sama dengan 1";i:1;s:22:"Tidak dapat ditentukan";i:2;s:18:"Lebih besar dari 1";i:3;s:18:"Lebih kecil dari 1";}', 'a:4:{i:0;s:17:"Always equal to 1";i:1;s:23:"Impossible to determine";i:2;s:14:"Greater than 1";i:3;s:11:"Less than 1";}', '', 'Lebih kecil dari 1', 'Less than 1', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000644', 'Pada kurva relative permeability, titik di mana kro dan krw berpotongan disebut...', 'On a relative permeability curve, the point where kro and krw intersect is called...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:19:"Endpoint saturation";i:1;s:18:"Residual oil point";i:2;s:15:"Crossover point";i:3;s:28:"Irreducible water saturation";}', 'a:4:{i:0;s:19:"Endpoint saturation";i:1;s:18:"Residual oil point";i:2;s:15:"Crossover point";i:3;s:28:"Irreducible water saturation";}', '', 'Crossover point', 'Crossover point', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000645', 'Pada batuan water-wet, air cenderung menempati...', 'In a water-wet rock, water tends to occupy...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:13:"Hanya rekahan";i:1;s:30:"Pori kecil dan permukaan butir";i:2;s:32:"Pori-pori besar di bagian tengah";i:3;s:22:"Rongga pelarutan besar";}', 'a:4:{i:0;s:14:"Fractures only";i:1;s:30:"Small pores and grain surfaces";i:2;s:25:"Large pores in the center";i:3;s:26:"Large dissolution cavities";}', '', 'Pori kecil dan permukaan butir', 'Small pores and grain surfaces', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000646', 'Bertambahnya tegangan efektif (effective stress) pada batuan reservoir umumnya menyebabkan...', 'Increasing effective stress in a reservoir rock generally causes...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:19:"Porositas meningkat";i:1;s:35:"Porositas dan permeabilitas menurun";i:2;s:19:"Tidak ada perubahan";i:3;s:23:"Permeabilitas meningkat";}', 'a:4:{i:0;s:20:"Porosity to increase";i:1;s:37:"Porosity and permeability to decrease";i:2;s:9:"No change";i:3;s:24:"Permeability to increase";}', '', 'Porositas dan permeabilitas menurun', 'Porosity and permeability to decrease', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000647', 'Persamaan Kozeny-Carman menunjukkan bahwa permeabilitas berbanding lurus dengan...', 'The Kozeny-Carman equation shows that permeability is directly proportional to...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:17:"Kadar air terikat";i:1;s:17:"Viskositas fluida";i:2;s:32:"Kuadrat diameter butir rata-rata";i:3;s:19:"Tegangan overburden";}', 'a:4:{i:0;s:19:"Bound water content";i:1;s:15:"Fluid viscosity";i:2;s:37:"The square of the mean grain diameter";i:3;s:17:"Overburden stress";}', '', 'Kuadrat diameter butir rata-rata', 'The square of the mean grain diameter', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000648', 'Rekahan pada reservoir tight umumnya berfungsi untuk...', 'Fractures in a tight reservoir generally serve to...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:28:"Menurunkan tekanan reservoir";i:1;s:48:"Menyediakan jalur aliran berpermeabilitas tinggi";i:2;s:28:"Mengurangi porositas matriks";i:3;s:25:"Meningkatkan saturasi air";}', 'a:4:{i:0;s:25:"Reduce reservoir pressure";i:1;s:36:"Provide high-permeability flow paths";i:2;s:22:"Reduce matrix porosity";i:3;s:25:"Increase water saturation";}', '', 'Menyediakan jalur aliran berpermeabilitas tinggi', 'Provide high-permeability flow paths', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000649', 'Penambahan lempung pada batupasir menurunkan permeabilitas terutama karena...', 'Adding clay to sandstone reduces permeability mainly because...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:25:"Lempung melarutkan kuarsa";i:1;s:38:"Lempung meningkatkan porositas efektif";i:2;s:29:"Lempung menambah ukuran butir";i:3;s:47:"Lempung menyumbat pori dan menambah tortuositas";}', 'a:4:{i:0;s:21:"Clay dissolves quartz";i:1;s:33:"Clay increases effective porosity";i:2;s:25:"Clay increases grain size";i:3;s:41:"Clay plugs pores and increases tortuosity";}', '', 'Lempung menyumbat pori dan menambah tortuositas', 'Clay plugs pores and increases tortuosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000650', 'Hukum Darcy berlaku paling tepat pada kondisi aliran...', 'Darcy''s law applies most appropriately under conditions of...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:27:"Aliran melalui pipa terbuka";i:1;s:8:"Turbulen";i:2;s:7:"Laminer";i:3;s:39:"Dua fase dengan viskositas tak terbatas";}', 'a:4:{i:0;s:25:"Flow through an open pipe";i:1;s:9:"Turbulent";i:2;s:7:"Laminar";i:3;s:34:"Two-phase with unbounded viscosity";}', '', 'Laminer', 'Laminar', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000651', 'Saturasi air ireduktibel (Swir) adalah saturasi air minimum yang...', 'Irreducible water saturation (Swir) is the minimum water saturation that...', 'option', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:34:"Masih dapat mengalir saat produksi";i:1;s:31:"Tidak dapat terproduksikan lagi";i:2;s:29:"Sama dengan saturasi air awal";i:3;s:19:"Selalu bernilai nol";}', 'a:4:{i:0;s:32:"Can still flow during production";i:1;s:25:"Can no longer be produced";i:2;s:35:"Equals the initial water saturation";i:3;s:14:"Is always zero";}', '', 'Tidak dapat terproduksikan lagi', 'Can no longer be produced', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000652', 'Manakah metode yang dapat digunakan untuk menentukan permeabilitas reservoir?', 'Which methods can be used to determine reservoir permeability?', 'multi', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:29:"Analisis core di laboratorium";i:1;s:21:"Uji sumur (well test)";i:2;s:22:"Korelasi dari data log";i:3;s:23:"Pengukuran warna batuan";}', 'a:4:{i:0;s:31:"Core analysis in the laboratory";i:1;s:12:"Well testing";i:2;s:25:"Correlation from log data";i:3;s:22:"Rock color measurement";}', '', 'a:3:{i:0;s:29:"Analisis core di laboratorium";i:1;s:21:"Uji sumur (well test)";i:2;s:22:"Korelasi dari data log";}', 'a:3:{i:0;s:31:"Core analysis in the laboratory";i:1;s:12:"Well testing";i:2;s:25:"Correlation from log data";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000653', 'Manakah pernyataan yang benar tentang relative permeability?', 'Which statements about relative permeability are correct?', 'multi', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:41:"Selalu bernilai sama untuk air dan minyak";i:1;s:29:"Nilai berkisar antara 0 dan 1";i:2;s:31:"Bergantung pada saturasi fluida";i:3;s:30:"Dipengaruhi wettability batuan";}', 'a:4:{i:0;s:36:"It is always equal for water and oil";i:1;s:32:"Its value ranges between 0 and 1";i:2;s:30:"It depends on fluid saturation";i:3;s:36:"It is influenced by rock wettability";}', '', 'a:3:{i:0;s:29:"Nilai berkisar antara 0 dan 1";i:1;s:31:"Bergantung pada saturasi fluida";i:2;s:30:"Dipengaruhi wettability batuan";}', 'a:3:{i:0;s:32:"Its value ranges between 0 and 1";i:1;s:30:"It depends on fluid saturation";i:2;s:36:"It is influenced by rock wettability";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000654', 'Manakah yang dapat menurunkan permeabilitas di sekitar lubang sumur (formation damage)?', 'Which of the following can reduce permeability around the wellbore (formation damage)?', 'multi', 'PFC000000002', 'Final Advanced', 'a:4:{i:0;s:40:"Migrasi partikel halus (fines migration)";i:1;s:19:"Pengendapan scaling";i:2;s:20:"Pembengkakan lempung";i:3;s:29:"Peningkatan tekanan reservoir";}', 'a:4:{i:0;s:15:"Fines migration";i:1;s:16:"Scale deposition";i:2;s:13:"Clay swelling";i:3;s:29:"Increasing reservoir pressure";}', '', 'a:3:{i:0;s:40:"Migrasi partikel halus (fines migration)";i:1;s:20:"Pembengkakan lempung";i:2;s:19:"Pengendapan scaling";}', 'a:3:{i:0;s:15:"Fines migration";i:1;s:13:"Clay swelling";i:2;s:16:"Scale deposition";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
